; address.asm -- chapter 19: an address of fourteen bits, and the VDP adding one
; generated by gen19.py
        INCLUDE "msx.inc"
        OUTPUT "address.rom"
        ORG $4000
        CART_HEADER init
VARS    EQU RAM_START + $100    ; the program's variables: the code is in ROM
        INCLUDE "bios.inc"
; A text at an address of two bytes; 64 bytes after one address, over two rows
; of the name table; eight bytes from $3FFC; and a row of character 0.
init:   di
        ld sp, SYS_AREA
        VDP_REG 1, $80          ; display off while the page is drawn
        VDP_REG 0, $00          ; Graphic I: 32 x 24 characters
        VDP_REG 2, $06          ; names              $1800
        VDP_REG 3, $80          ; colours            $2000
        VDP_REG 4, $00          ; patterns           $0000
        VDP_REG 5, $36          ; sprite attributes  $1B00
        VDP_REG 6, $07          ; sprite patterns    $3800
        VDP_REG 7, $0F          ; border white
        VRAM_WRITE $0000        ; the BIOS character set: 256 x 8 bytes
        ld hl, (CGTABL)
        ld bc, 2048
.font:  ld a, (hl)
        out (VDP_DATA), a
        inc hl
        dec bc
        ld a, b
        or c
        jr nz, .font
        VRAM_WRITE $0008        ; characters 1 and 2: the bit boxes
        ld hl, boxes
        ld b, 16
.box:   ld a, (hl)
        out (VDP_DATA), a
        inc hl
        djnz .box
        VRAM_WRITE $2000        ; colours: black ink (1) on white paper (15)
        ld b, 32
        ld a, $1F
.col:   out (VDP_DATA), a
        djnz .col
        VRAM_WRITE $1800        ; names: all spaces
        ld bc, 768
.clr:   ld a, ' '
        out (VDP_DATA), a
        dec bc
        ld a, b
        or c
        jr nz, .clr
        VRAM_WRITE $1B00        ; no sprites
        ld a, $D0
        out (VDP_DATA), a
        VRAM_WRITE $1842        ; two bytes: $42, then $58
        ld hl, title
        call send
        VRAM_WRITE $18A0        ; one address for all 64 bytes
        ld hl, long
        call send
        VRAM_WRITE $1904
        ld hl, label
        call send
        VRAM_WRITE $1944        ; a row of character 0
        ld b, 24
        xor a
c0:     out (VDP_DATA), a       ; 12
        nop                     ;  5
        nop                     ;  5
        djnz c0                 ; 14: 36 a byte
wr:     VRAM_WRITE $3FFC        ; eight bytes from the top of the VRAM
        ld b, 8
        ld a, $FF               ; every pixel ink
w8:     out (VDP_DATA), a
        nop
        nop
        djnz w8
w9:
        VDP_REG 1, $C0          ; display on: the page is finished
done:   jr done

; send: the text at HL, ending in 0, to the VRAM from its current address
send:   ld a, (hl)              ;  8
        or a                    ;  5
        ret z                   ;  6
        out (VDP_DATA), a       ; 12
        inc hl                  ;  7
        jr send                 ; 13: 51 a byte
title:        db "$1842: TWO BYTES, $42 THEN $58", 0
long:        db "ONE ADDRESS AND 64 BYTES: AFTER EACH BYTE THE VDP ADDS ONE TO IT", 0
label:        db "24 CELLS OF CHARACTER 0:", 0

; at: B = row (0-23), C = column (0-31) -> the VDP's write address is that
;     cell of the name table. Keeps BC, DE. Uses A, HL.
at:     push de
        ld l, b
        ld h, 0
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl
        add hl, hl              ; row x 32
        ld e, c
        ld d, $18
        add hl, de              ; + $1800 + column
        ld a, l
        out (VDP_CTRL), a
        ld a, h
        or $40
        out (VDP_CTRL), a
        pop de
        ret

; putc: A = character, B = row, C = column. Keeps BC, DE, HL.
putc:   push hl
        push af
        call at
        pop af
        out (VDP_DATA), a
        pop hl
        ret

; puts: HL = text ending in 0, B = row, C = column; C moves on.
puts:   ld a, (hl)
        or a
        ret z
        call putc
        inc hl
        inc c
        jr puts

; puthex: A = a byte, as two hexadecimal digits; C moves on by 2.
puthex: push af
        rrca
        rrca
        rrca
        rrca                    ; the high four bits first
        call hexdig
        pop af
hexdig: and %00001111
        add a, '0'
        cp '9' + 1
        jr c, .digit
        add a, 'A' - '9' - 1    ; 10-15 become A-F
.digit: call putc
        inc c
        ret
boxes:                          ; characters 1 (empty box) and 2 (filled)
        db %11111110, %10000010, %10000010, %10000010, %10000010, %10000010, %11111110, %00000000
        db %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %11111110, %00000000
        ASSERT $ <= $8000, the program is longer than the cartridge
        ds $8000 - $, $FF       ; pad the cartridge to 16 KB
